// src/shared/effects/parametricCanvas.ts
// Canvas-based effect renderers (particles, lightning)

import type { EffectParams } from "./parametricEffects";

interface Particle {
  x: number; y: number;
  vx: number; vy: number;
  life: number; maxLife: number; // life goes from 1.0 down to 0
  sizeStart: number;
  sizeEnd: number;
  colorStart: [number, number, number, number];
  colorEnd: [number, number, number, number];
  shape: string;
}

// Per-element particle state (keyed by element id)
const particleState = new Map<string, { particles: Particle[]; lastT: number }>();

function parseColor(color: string): [number, number, number, number] {
  const trimmed = color.trim().toLowerCase();
  if (trimmed.startsWith("#")) {
    const hex = trimmed.substring(1);
    if (hex.length === 3) {
      const r = parseInt(hex[0] + hex[0], 16) || 0;
      const g = parseInt(hex[1] + hex[1], 16) || 0;
      const b = parseInt(hex[2] + hex[2], 16) || 0;
      return [r, g, b, 1];
    }
    if (hex.length === 6) {
      const r = parseInt(hex.substring(0, 2), 16) || 0;
      const g = parseInt(hex.substring(2, 4), 16) || 0;
      const b = parseInt(hex.substring(4, 6), 16) || 0;
      return [r, g, b, 1];
    }
    if (hex.length === 8) {
      const r = parseInt(hex.substring(0, 2), 16) || 0;
      const g = parseInt(hex.substring(2, 4), 16) || 0;
      const b = parseInt(hex.substring(4, 6), 16) || 0;
      const a = (parseInt(hex.substring(6, 8), 16) || 0) / 255;
      return [r, g, b, a];
    }
  }
  if (trimmed.startsWith("rgb")) {
    const match = trimmed.match(/[\d.]+/g);
    if (match && match.length >= 3) {
      const r = parseFloat(match[0]) || 0;
      const g = parseFloat(match[1]) || 0;
      const b = parseFloat(match[2]) || 0;
      const a = match.length >= 4 ? parseFloat(match[3]) : 1;
      return [r, g, b, a];
    }
  }
  if (trimmed === "transparent") return [0, 0, 0, 0];
  if (trimmed === "black") return [0, 0, 0, 1];
  if (trimmed === "red") return [255, 0, 0, 1];
  if (trimmed === "green") return [0, 255, 0, 1];
  if (trimmed === "blue") return [0, 0, 255, 1];
  if (trimmed === "yellow") return [255, 255, 0, 1];
  return [255, 255, 255, 1]; // fallback white
}

function interpolateColor(c1: [number, number, number, number], c2: [number, number, number, number], ratio: number): string {
  const r = Math.round(c1[0] + (c2[0] - c1[0]) * ratio);
  const g = Math.round(c1[1] + (c2[1] - c1[1]) * ratio);
  const b = Math.round(c1[2] + (c2[2] - c1[2]) * ratio);
  const a = c1[3] + (c2[3] - c1[3]) * ratio;
  return `rgba(${r}, ${g}, ${b}, ${a})`;
}

export function renderParticleEmitter(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: EffectParams,
  t: number,
  elementId: string
) {
  const color = String(params.color ?? "#ffffff");
  const colorEnd = String(params.colorEnd ?? color);
  const count = Number(params.count ?? 30);
  const size = Number(params.size ?? 3);
  const sizeEnd = Number(params.sizeEnd ?? 0);
  const speed = Number(params.speed ?? 1);
  const speedSpread = Number(params.speedSpread ?? 0.5);
  const angle = Number(params.angle ?? 270);
  const angleSpread = Number(params.angleSpread ?? 45);
  const gravity = Number(params.gravity ?? 0.1);
  const wind = Number(params.wind ?? 0);
  const lifetime = Number(params.lifetime ?? 1.0);
  const emitterX = Number(params.emitterX ?? 50);
  const emitterY = Number(params.emitterY ?? 50);
  const emitterWidth = Number(params.emitterWidth ?? 30);
  const emitterHeight = Number(params.emitterHeight ?? 30);
  const fade = params.fade !== false;
  const shape = String(params.shape ?? "circle");

  let state = particleState.get(elementId);
  if (!state) {
    state = { particles: [], lastT: t };
    particleState.set(elementId, state);
  }

  const dt = Math.min(50, t - state.lastT) / 16.67; // normalized to 60fps
  state.lastT = t;

  // Emit new particles
  const emitRate = (count / 60) * speed * dt;
  const parsedColorStart = parseColor(color);
  const parsedColorEnd = parseColor(colorEnd);

  for (let i = 0; i < emitRate; i++) {
    // Positioning
    const eX = (emitterX / 100) * width;
    const eY = (emitterY / 100) * height;
    const eW = (emitterWidth / 100) * width;
    const eH = (emitterHeight / 100) * height;

    const spawnX = eX + (Math.random() - 0.5) * eW;
    const spawnY = eY + (Math.random() - 0.5) * eH;

    // Angle and direction
    const angleRad = (angle * Math.PI) / 180;
    const spreadRad = (angleSpread * Math.PI) / 180;
    const pAngle = angleRad + (Math.random() - 0.5) * spreadRad;

    // Speed and velocity dispersion
    const pSpeed = speed * 2 * (1 - Math.random() * speedSpread);
    const vx = Math.cos(pAngle) * pSpeed;
    const vy = Math.sin(pAngle) * pSpeed;

    // Lifetime randomization around the target lifetime (80% to 120%)
    const pMaxLife = lifetime * (0.8 + Math.random() * 0.4);

    state.particles.push({
      x: spawnX,
      y: spawnY,
      vx,
      vy,
      life: 1,
      maxLife: pMaxLife,
      sizeStart: size * (0.5 + Math.random() * 0.5),
      sizeEnd: sizeEnd * (0.5 + Math.random() * 0.5),
      colorStart: parsedColorStart,
      colorEnd: parsedColorEnd,
      shape,
    });
  }

  // Update and draw
  state.particles = state.particles.filter(p => p.life > 0);

  for (const p of state.particles) {
    // Apply forces
    p.vx += wind * dt;
    p.vy += gravity * dt;

    p.x += p.vx * dt;
    p.y += p.vy * dt;

    // Progress lifetime
    p.life -= dt / (p.maxLife * 60);

    const ratio = Math.min(1, Math.max(0, 1 - p.life));
    const drawSize = Math.max(0, p.sizeStart + (p.sizeEnd - p.sizeStart) * ratio);

    if (drawSize <= 0) continue;

    const alpha = fade ? Math.max(0, p.life) : 1;
    ctx.globalAlpha = alpha;

    const colorRGB = interpolateColor(p.colorStart, p.colorEnd, ratio);
    ctx.fillStyle = colorRGB;
    ctx.strokeStyle = colorRGB;

    if (p.shape === "circle") {
      ctx.beginPath();
      ctx.arc(p.x, p.y, drawSize, 0, Math.PI * 2);
      ctx.fill();
    } else if (p.shape === "square") {
      ctx.fillRect(p.x - drawSize / 2, p.y - drawSize / 2, drawSize, drawSize);
    } else if (p.shape === "spark") {
      ctx.beginPath();
      ctx.moveTo(p.x, p.y);
      ctx.lineTo(p.x - p.vx * 3, p.y - p.vy * 3);
      ctx.lineWidth = drawSize * 0.5;
      ctx.stroke();
    } else if (p.shape === "star") {
      drawStar(ctx, p.x, p.y, drawSize, 5);
      ctx.fill();
    }
  }
  ctx.globalAlpha = 1;
}

function drawStar(ctx: CanvasRenderingContext2D, x: number, y: number, r: number, points: number) {
  ctx.beginPath();
  for (let i = 0; i < points * 2; i++) {
    const angle = (i * Math.PI) / points - Math.PI / 2;
    const radius = i % 2 === 0 ? r : r * 0.4;
    if (i === 0) ctx.moveTo(x + Math.cos(angle) * radius, y + Math.sin(angle) * radius);
    else ctx.lineTo(x + Math.cos(angle) * radius, y + Math.sin(angle) * radius);
  }
  ctx.closePath();
}

export function renderLightningArc(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: EffectParams,
  t: number
) {
  const color = String(params.color ?? "#88aaff");
  const branches = Number(params.branches ?? 3);
  const intensity = Number(params.intensity ?? 1);
  const speed = Number(params.speed ?? 1);

  // clearRect handled by caller before clip is applied

  // Regenerate lightning path every ~speed frames
  const seed = Math.floor(t * speed / 50);

  const rng = (s: number) => ((Math.sin(s * 127.1 + 311.7) * 43758.5453) % 1 + 1) % 1;

  const drawBolt = (x1: number, y1: number, x2: number, y2: number, depth: number, s: number) => {
    if (depth <= 0) return;
    const mx = (x1 + x2) / 2 + (rng(s) - 0.5) * 60 * intensity;
    const my = (y1 + y2) / 2 + (rng(s + 1) - 0.5) * 60 * intensity;

    ctx.beginPath();
    ctx.moveTo(x1, y1);
    ctx.lineTo(mx, my);
    ctx.lineTo(x2, y2);
    ctx.strokeStyle = color;
    ctx.lineWidth = depth * intensity;
    ctx.globalAlpha = 0.3 + depth * 0.2;
    ctx.shadowBlur = 10 * intensity;
    ctx.shadowColor = color;
    ctx.stroke();

    if (depth > 1 && rng(s + 2) > 0.5) {
      const bx = mx + (rng(s + 3) - 0.5) * width * 0.3;
      const by = my + (rng(s + 4) - 0.5) * height * 0.3;
      drawBolt(mx, my, bx, by, depth - 1, s + 10);
    }

    drawBolt(x1, y1, mx, my, depth - 1, s + 5);
    drawBolt(mx, my, x2, y2, depth - 1, s + 7);
  };

  for (let i = 0; i < branches; i++) {
    const x1 = rng(seed + i * 3) * width;
    const y1 = rng(seed + i * 3 + 1) * height;
    const x2 = rng(seed + i * 3 + 2) * width;
    const y2 = rng(seed + i * 3 + 3) * height;
    drawBolt(x1, y1, x2, y2, 3, seed + i * 100);
  }

  ctx.globalAlpha = 1;
  ctx.shadowBlur = 0;
}


// ── Snowfall ──────────────────────────────────────────────────────────────────
const snowState = new Map<string, { particles: any[]; lastT: number }>();

export function renderSnowfall(
  ctx: CanvasRenderingContext2D, width: number, height: number,
  params: import("./parametricEffects").EffectParams, t: number, elementId: string
) {
  const count = Number(params.count ?? 40);
  const speed = Number(params.speed ?? 1);
  const size = Number(params.size ?? 3);
  const color = String(params.color ?? "#ffffff");
  const wind = Number(params.wind ?? 0.3);

  let state = snowState.get(elementId);
  if (!state) { state = { particles: [], lastT: t }; snowState.set(elementId, state); }
  const dt = Math.min(50, t - state.lastT) / 16.67;
  state.lastT = t;

  // Seed initial particles spread across the element
  while (state.particles.length < count) {
    state.particles.push({
      x: Math.random() * width,
      y: Math.random() * height,
      vx: (Math.random() - 0.5) * 0.5 + wind,
      vy: (0.3 + Math.random() * 0.7) * speed * 1.5,
      r: size * (0.4 + Math.random() * 0.6),
      wobble: Math.random() * Math.PI * 2,
    });
  }

  // clearRect handled by caller before clip is applied
  for (const p of state.particles) {
    p.wobble += 0.03 * dt;
    p.x += (p.vx + Math.sin(p.wobble) * 0.3) * dt;
    p.y += p.vy * dt;
    if (p.y > height + p.r) { p.y = -p.r; p.x = Math.random() * width; }
    if (p.x > width + p.r) p.x = -p.r;
    if (p.x < -p.r) p.x = width + p.r;
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.globalAlpha = 0.7 + Math.sin(p.wobble) * 0.3;
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

export function cleanupSnowState(id: string) { snowState.delete(id); }

// ── Rain ──────────────────────────────────────────────────────────────────────
const rainState = new Map<string, { drops: any[]; lastT: number }>();

export function renderRain(
  ctx: CanvasRenderingContext2D, width: number, height: number,
  params: import("./parametricEffects").EffectParams, t: number, elementId: string
) {
  const count = Number(params.count ?? 60);
  const speed = Number(params.speed ?? 1);
  const angleDeg = Number(params.angle ?? 15);
  const length = Number(params.length ?? 12);
  const color = String(params.color ?? "#88aaff");
  const rad = angleDeg * Math.PI / 180;
  const vx = Math.sin(rad) * speed * 4;
  const vy = Math.cos(rad) * speed * 8;

  let state = rainState.get(elementId);
  if (!state) { state = { drops: [], lastT: t }; rainState.set(elementId, state); }
  const dt = Math.min(50, t - state.lastT) / 16.67;
  state.lastT = t;

  while (state.drops.length < count) {
    state.drops.push({ x: Math.random() * (width + 40) - 20, y: Math.random() * height });
  }

  // clearRect handled by caller before clip is applied
  ctx.strokeStyle = color;
  ctx.lineWidth = 1;
  ctx.globalAlpha = 0.6;
  for (const d of state.drops) {
    d.x += vx * dt;
    d.y += vy * dt;
    if (d.y > height + length) { d.y = -length; d.x = Math.random() * (width + 40) - 20; }
    ctx.beginPath();
    ctx.moveTo(d.x, d.y);
    ctx.lineTo(d.x - vx / vy * length, d.y - length);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
}

export function cleanupRainState(id: string) { rainState.delete(id); }

// ── Fire ──────────────────────────────────────────────────────────────────────
const fireState = new Map<string, { particles: any[]; lastT: number }>();

export function renderFireEmitter(
  ctx: CanvasRenderingContext2D, width: number, height: number,
  params: import("./parametricEffects").EffectParams, t: number, elementId: string
) {
  const intensity = Number(params.intensity ?? 1);
  const spread = Number(params.spread ?? 0.5);
  const speed = Number(params.speed ?? 1);
  const baseColor = String(params.color ?? "#ff4400");

  // Parse base color to get hue for gradient
  const count = Math.round(30 * intensity);

  let state = fireState.get(elementId);
  if (!state) { state = { particles: [], lastT: t }; fireState.set(elementId, state); }
  const dt = Math.min(50, t - state.lastT) / 16.67;
  state.lastT = t;

  const emitRate = count / 60 * speed * dt;
  for (let i = 0; i < emitRate; i++) {
    state.particles.push({
      x: width * (0.2 + Math.random() * 0.6),
      y: height,
      vx: (Math.random() - 0.5) * spread * 3,
      vy: -(1 + Math.random()) * speed * 3,
      life: 1,
      size: 4 + Math.random() * 8 * intensity,
    });
  }

  // clearRect handled by caller before clip is applied
  state.particles = state.particles.filter((p: any) => p.life > 0);
  for (const p of state.particles) {
    p.x += p.vx * dt;
    p.y += p.vy * dt;
    p.vx += (Math.random() - 0.5) * 0.3 * dt;
    p.life -= dt / 25;
    const alpha = Math.max(0, p.life);
    // Colour shifts from white->yellow->orange->red as life decreases
    const r = 255;
    const g = Math.round(Math.max(0, p.life * 2 - 0.5) * 200);
    const b = Math.round(Math.max(0, p.life * 3 - 2) * 100);
    const radius = Math.max(0.1, p.size * p.life);
    ctx.beginPath();
    ctx.arc(p.x, p.y, radius, 0, Math.PI * 2);
    ctx.fillStyle = `rgb(${r},${g},${b})`;
    ctx.globalAlpha = alpha * 0.8;
    ctx.fill();
  }
  ctx.globalAlpha = 1;
}

export function cleanupFireState(id: string) { fireState.delete(id); }



export function cleanupParticleState(elementId: string) {
  particleState.delete(elementId);
}

// ── Film Grain ────────────────────────────────────────────────────────────────
// Uses ImageData + fast integer RNG (xorshift) for performance.
// Writes directly to pixel buffer — no per-pixel fillRect or Math.sin.
const _grainBuffers = new Map<string, { buf: Uint8ClampedArray; w: number; h: number }>();

export function renderFilmGrain(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: EffectParams,
  t: number,
  elementId: string
) {
  const intensity = Math.min(1, Math.max(0, Number(params.intensity ?? 0.15)));
  const grainSize = Math.max(1, Math.round(Number(params.size ?? 1)));
  const colored = params.colored === true;
  const speed = Number(params.speed ?? 1);
  const opacity = Number(params.opacity ?? 1);

  // Work at reduced resolution then scale up — huge perf win
  const gw = Math.ceil(width / grainSize);
  const gh = Math.ceil(height / grainSize);
  const pixelCount = gw * gh;

  // Reuse buffer if same size
  let cached = _grainBuffers.get(elementId);
  if (!cached || cached.w !== gw || cached.h !== gh) {
    cached = { buf: new Uint8ClampedArray(gw * gh * 4), w: gw, h: gh };
    _grainBuffers.set(elementId, cached);
  }
  const buf = cached.buf;

  // Fast xorshift32 RNG — seed changes each frame based on time
  let rng = (Math.floor(t * speed / 40) * 1664525 + 1013904223) >>> 0;
  const next = () => { rng ^= rng << 13; rng ^= rng >>> 17; rng ^= rng << 5; return rng >>> 0; };

  // Alpha scaled by intensity (0-255)
  const alpha = Math.round(intensity * 255);

  for (let i = 0; i < pixelCount; i++) {
    const v = next();
    const idx = i * 4;
    if (colored) {
      buf[idx]     = (v & 0xff);
      buf[idx + 1] = ((v >> 8) & 0xff);
      buf[idx + 2] = ((v >> 16) & 0xff);
    } else {
      const lum = v & 0xff;
      buf[idx] = buf[idx + 1] = buf[idx + 2] = lum;
    }
    buf[idx + 3] = alpha;
  }

  // Create ImageData at grain resolution and draw scaled up
  const imgData = new ImageData(buf, gw, gh);

  // Draw to a temp offscreen canvas at grain size, then scale to element size
  const offscreen = new OffscreenCanvas(gw, gh);
  const offCtx = offscreen.getContext('2d')!;
  offCtx.putImageData(imgData, 0, 0);

  ctx.save();
  ctx.globalAlpha = opacity;
  ctx.globalCompositeOperation = 'overlay';
  // Scale up with pixelated rendering for sharp grain
  (ctx as any).imageSmoothingEnabled = false;
  ctx.drawImage(offscreen, 0, 0, width, height);
  ctx.restore();
}

export function cleanupGrainState(elementId: string) {
  _grainBuffers.delete(elementId);
}

// ── Tape Noise ────────────────────────────────────────────────────────────────
export function renderTapeNoise(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: EffectParams,
  t: number,
  elementId: string
) {
  const density = Number(params.density ?? 0.05);
  const bandHeight = Math.max(1, Number(params.bandHeight ?? 3));
  const intensity = Number(params.intensity ?? 0.6);
  const colorNoise = params.colorNoise === true;
  const speed = Number(params.speed ?? 1);
  const opacity = Number(params.opacity ?? 1);

  const seed = Math.floor(t * speed / 100);
  const rng = (s: number) => ((Math.sin(s * 127.1 + 311.7) * 43758.5453) % 1 + 1) % 1;

  ctx.save();
  ctx.globalAlpha = opacity;

  const rows = Math.ceil(height / bandHeight);
  for (let row = 0; row < rows; row++) {
    const r = rng(row * 3.7 + seed);
    if (r > density) continue;

    const y = row * bandHeight;
    const noiseIntensity = intensity * rng(row * 7.1 + seed + 1);
    const xOffset = (rng(row * 5.3 + seed + 2) - 0.5) * width * 0.3;

    if (colorNoise) {
      const hue = Math.round(rng(row + seed + 3) * 360);
      ctx.fillStyle = `hsla(${hue}, 100%, 70%, ${noiseIntensity})`;
    } else {
      const v = Math.round(rng(row * 2.1 + seed + 4) * 255);
      ctx.fillStyle = `rgba(${v},${v},${v},${noiseIntensity})`;
    }

    // Draw a horizontal band with slight x offset (tape tracking artifact)
    ctx.fillRect(xOffset, y, width - Math.abs(xOffset), bandHeight);
    // Fill the gap left by offset
    if (xOffset > 0) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, y, xOffset, bandHeight);
    } else if (xOffset < 0) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(width + xOffset, y, -xOffset, bandHeight);
    }
  }
  ctx.restore();
}

// ── Ripple Effector ───────────────────────────────────────────────────────────
export function renderRipple(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  params: EffectParams,
  t: number
) {
  const color = String(params.color ?? "#00ffff");
  const waveType = String(params.waveType ?? "sine");
  const waveDirection = String(params.waveDirection ?? "radial");
  const rings = Math.round(Number(params.rings ?? 3));
  const speed = Number(params.speed ?? 1);
  const thickness = Number(params.thickness ?? 2);
  const maxScale = Number(params.maxScale ?? 2);
  const opacity = Number(params.opacity ?? 1);
  const gridSpacing = Math.max(10, Math.round(Number(params.gridSpacing ?? 20)));
  const displacement = Number(params.displacement ?? 15);
  const dotSize = Number(params.dotSize ?? 2);
  const showGridLines = params.showGridLines !== false;
  const showWaveRing = params.showWaveRing !== false;

  // Custom colors & opacities
  const gridColor = String(params.gridColor ?? color);
  const gridOpacity = Number(params.gridOpacity ?? 0.25);
  const dotColor = String(params.dotColor ?? color);
  const dotOpacity = Number(params.dotOpacity ?? 0.6);
  const waveColor = String(params.waveColor ?? color);
  const waveOpacity = Number(params.waveOpacity ?? 0.4);

  const cx = width / 2;
  const cy = height / 2;
  const maxRadius = Math.max(width, height) * 0.5 * maxScale;
  const waveWidth = thickness * 15; // wide enough to feel smooth

  const cols = Math.ceil(width / gridSpacing) + 1;
  const rows = Math.ceil(height / gridSpacing) + 1;

  const grid: { x: number; y: number; amp: number }[][] = [];
  for (let c = 0; c < cols; c++) {
    grid[c] = [];
    for (let r = 0; r < rows; r++) {
      const origX = c * gridSpacing;
      const origY = r * gridSpacing;

      const dx = origX - cx;
      const dy = origY - cy;

      // Distance metric based on wave direction
      let d = 0;
      if (waveDirection === "radial") {
        d = Math.sqrt(dx * dx + dy * dy);
      } else if (waveDirection === "horizontal") {
        d = Math.abs(origX - cx);
      } else if (waveDirection === "vertical") {
        d = Math.abs(origY - cy);
      }

      let finalX = origX;
      let finalY = origY;
      let maxAmp = 0;

      // Calculate cumulative displacement from all active rings/waves
      for (let i = 0; i < rings; i++) {
        const phase = ((t / 1000 * speed + i / rings) % 1);
        const currentRadius = maxRadius * phase;
        
        const distToWave = Math.abs(d - currentRadius);
        if (distToWave < waveWidth) {
          const intensity = 1 - distToWave / waveWidth; // 1 at center of wave, 0 at edge
          let waveShape = 0;
          if (waveType === "sine") {
            waveShape = Math.sin(intensity * Math.PI * 0.5);
          } else if (waveType === "triangle") {
            waveShape = intensity;
          } else if (waveType === "sawtooth") {
            waveShape = intensity * intensity;
          } else if (waveType === "square") {
            waveShape = intensity > 0.4 ? 1 : 0;
          } else {
            waveShape = Math.sin(intensity * Math.PI * 0.5);
          }

          const ringAmp = waveShape * (1 - phase); // fade out as it reaches the edge
          if (ringAmp > maxAmp) {
            maxAmp = ringAmp;
          }
        }
      }

      if (maxAmp > 0) {
        // Displace based on wave direction and location
        if (waveDirection === "radial") {
          if (d > 0) {
            const pX = dx / d;
            const pY = dy / d;
            finalX += pX * displacement * maxAmp;
            finalY += pY * displacement * maxAmp;
          }
        } else if (waveDirection === "horizontal") {
          const pX = dx >= 0 ? 1 : -1;
          finalX += pX * displacement * maxAmp;
        } else if (waveDirection === "vertical") {
          const pY = dy >= 0 ? 1 : -1;
          finalY += pY * displacement * maxAmp;
        }
      }

      grid[c][r] = { x: finalX, y: finalY, amp: maxAmp };
    }
  }

  ctx.save();
  ctx.globalAlpha = opacity;

  // Draw grid lines
  if (showGridLines && gridSpacing > 0) {
    ctx.strokeStyle = gridColor;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        const node = grid[c][r];
        // Line to right
        if (c < cols - 1) {
          const rightNode = grid[c + 1][r];
          const lineAlpha = (0.08 + (node.amp + rightNode.amp) * 0.25) * gridOpacity;
          ctx.globalAlpha = opacity * lineAlpha;
          ctx.lineWidth = 1 + (node.amp + rightNode.amp) * 0.5;
          ctx.beginPath();
          ctx.moveTo(node.x, node.y);
          ctx.lineTo(rightNode.x, rightNode.y);
          ctx.stroke();
        }
        // Line to down
        if (r < rows - 1) {
          const downNode = grid[c][r + 1];
          const lineAlpha = (0.08 + (node.amp + downNode.amp) * 0.25) * gridOpacity;
          ctx.globalAlpha = opacity * lineAlpha;
          ctx.lineWidth = 1 + (node.amp + downNode.amp) * 0.5;
          ctx.beginPath();
          ctx.moveTo(node.x, node.y);
          ctx.lineTo(downNode.x, downNode.y);
          ctx.stroke();
        }
      }
    }
  }

  // Draw dots
  if (dotSize > 0) {
    ctx.fillStyle = dotColor;
    for (let c = 0; c < cols; c++) {
      for (let r = 0; r < rows; r++) {
        const node = grid[c][r];
        const currentSize = dotSize + dotSize * 1.5 * node.amp;
        const dotAlpha = (0.15 + node.amp * 0.8) * dotOpacity;
        ctx.globalAlpha = opacity * dotAlpha;
        
        ctx.beginPath();
        ctx.arc(node.x, node.y, currentSize, 0, Math.PI * 2);
        ctx.fill();
      }
    }
  }

  // Draw the actual expanding wave as soft glows
  if (showWaveRing) {
    ctx.strokeStyle = waveColor;
    for (let i = 0; i < rings; i++) {
      const phase = ((t / 1000 * speed + i / rings) % 1);
      const currentRadius = maxRadius * phase;
      const ringAlpha = (1 - phase) * waveOpacity;
      if (ringAlpha > 0) {
        ctx.globalAlpha = opacity * ringAlpha;
        ctx.lineWidth = thickness;
        
        if (waveDirection === "radial") {
          ctx.beginPath();
          ctx.arc(cx, cy, currentRadius, 0, Math.PI * 2);
          ctx.stroke();
        } else if (waveDirection === "horizontal") {
          ctx.beginPath();
          ctx.moveTo(cx - currentRadius, 0);
          ctx.lineTo(cx - currentRadius, height);
          ctx.moveTo(cx + currentRadius, 0);
          ctx.lineTo(cx + currentRadius, height);
          ctx.stroke();
        } else if (waveDirection === "vertical") {
          ctx.beginPath();
          ctx.moveTo(0, cy - currentRadius);
          ctx.lineTo(width, cy - currentRadius);
          ctx.moveTo(0, cy + currentRadius);
          ctx.lineTo(width, cy + currentRadius);
          ctx.stroke();
        }
      }
    }
  }

  ctx.restore();
}

